//! Cross-validation against GnuTLS AES-128-SIV output (generated by
//! /tmp/siv128_ref.c). These pin our SIV to the exact construction chrony
//! uses for NTS AEAD id 15.

use nts::aead::AeadAlg;

#[test]
fn matches_gnutls_aes128_siv_vectors() {
    let key: Vec<u8> = (1..=32u8).collect();
    let nonce: Vec<u8> = (0xA0..=0xAF).collect();
    let aad = vec![0x55u8; 48];

    // Empty plaintext -> 16-byte synthetic IV only.
    let seal_empty = AeadAlg::AesSivCmac256
        .seal(&key, &nonce, &aad, &[])
        .unwrap();
    assert_eq!(
        seal_empty.iter().map(|b| format!("{b:02x}")).collect::<String>(),
        "c31e9cf0ca0cb914d20a08f1b4a26543"
    );

    // 10-byte plaintext.
    let pt: Vec<u8> = (0..10).collect();
    let seal_10 = AeadAlg::AesSivCmac256
        .seal(&key, &nonce, &aad, &pt)
        .unwrap();
    assert_eq!(
        seal_10.iter().map(|b| format!("{b:02x}")).collect::<String>(),
        "46a774f4fa4d07d38752ebebf0d35947755ae2af54317c6675b8"
    );

    // Round-trip the empty case.
    let opened = AeadAlg::AesSivCmac256
        .open(&key, &nonce, &aad, &seal_empty)
        .unwrap();
    assert!(opened.is_empty());
}
